// The files of the private infrastructure repository (G-0026), generated by
// `harness infra init`: one thin caller per reusable infrastructure workflow of the harness,
// pinned to a harness tag, and a README. Nothing in them identifies the infrastructure: no
// host, address, dataset or token. Those live in the environment's secrets and on the NAS.
import { HARNESS_REPO } from '../create.mjs';

export const SECRETS = ['NETLIFY_AUTH_TOKEN', 'TS_OAUTH_CLIENT_ID', 'TS_OAUTH_SECRET', 'TRUENAS_API_KEY'];
// Not needed until spin-up pulls a private project's backend image; reported, never required.
export const LATER_SECRETS = { GHCR_PULL_TOKEN: "for pulling a private project's backend image, from 0.7.0" };

const header = (ref) => `# Generated by harness infra init, pinned to harness ${ref}. Don't edit it: run
# harness infra init again, which rewrites every file here through a pull request.`;

// A workflow_dispatch input block.
const input = (name, { type = 'string', description, required = false, def }) =>
  [`      ${name}:`, `        description: ${JSON.stringify(description)}`, `        type: ${type}`, required ? '        required: true' : `        default: ${def}`].join('\n');

// Each caller: the reusable workflow it calls and the inputs it passes on.
export const CALLERS = [
  {
    file: 'nas.yml',
    name: 'nas',
    reusable: 'infra-nas.yml',
    job: 'nas',
    inputs: [
      ['method', { description: 'The TrueNAS API method, e.g. core.ping', required: true }],
      ['params', { description: 'Its parameters, as a JSON array', def: "'[]'" }],
      ['job', { type: 'boolean', description: 'The method starts a job; wait for it', def: 'false' }],
      ['confirmed', { type: 'boolean', description: 'A destructive method, confirmed by the Engineer in chat', def: 'false' }],
    ],
  },
  { file: 'check.yml', name: 'check', reusable: 'infra-check.yml', job: 'check', inputs: [] },
  {
    file: 'project-up.yml',
    name: 'project-up',
    reusable: 'infra-project-up.yml',
    job: 'up',
    inputs: [
      ['project', { description: "The project's name", required: true }],
      ['repository', { description: 'Its repository, as owner/name', required: true }],
      ['sync', { type: 'boolean', description: 'The project syncs: it gets a backend', def: 'false' }],
      ['funnel-paths', { description: 'The paths the internet may reach, as a JSON list', def: "'[]'" }],
      ['installation-id', { description: "The Netlify GitHub App's installation id", def: "''" }],
    ],
  },
  {
    file: 'project-down.yml',
    name: 'project-down',
    reusable: 'infra-project-down.yml',
    job: 'down',
    inputs: [
      ['project', { description: "The project's name", required: true }],
      ['confirmation', { description: "The project's name once more, as the Engineer's yes", required: true }],
    ],
  },
];

export function callerWorkflow(caller, { ref, environment }) {
  const inputs = [...caller.inputs, ['request-id', { description: 'Names the run, so the harness finds it again', def: "''" }]];
  return `${header(ref)}
name: "${caller.name}"
run-name: "${caller.name} \${{ inputs.request-id }}"

on:
  workflow_dispatch:
    inputs:
${inputs.map(([name, o]) => input(name, o)).join('\n')}

permissions:
  contents: read

jobs:
  ${caller.job}:
    uses: ${HARNESS_REPO}/.github/workflows/${caller.reusable}@${ref}
    secrets: inherit
    with:
      environment: ${environment}
      harness-ref: ${ref}
${inputs.map(([name]) => `      ${name}: \${{ inputs.${name} }}`).join('\n')}
`;
}

export function readme({ ref, environment }) {
  return `# Infrastructure

The Engineer's private infrastructure repository (G-0026 in the harness). Its workflows
create and change the infrastructure of the Engineer's projects; the secrets they need are in
this repository's GitHub environment \`${environment}\`.

**Every file here is generated** by \`harness infra init\`, pinned to harness ${ref}. Don't
edit them: run \`harness infra init\` again, which rewrites them through a pull request.

| Workflow | Started by | What |
| --- | --- | --- |
${CALLERS.map((c) => `| \`${c.file}\` | ${c.file === 'nas.yml' ? '`harness nas --remote`' : c.file === 'check.yml' ? '`harness infra init`, or by hand' : '`harness infra up` / `down` (from 0.7.0)'} | calls the harness's \`${c.reusable}\` |`).join('\n')}

The jobs that reach the NAS run on the self-hosted runner on the NAS (\`harness infra runner
install\`), labelled \`harness-nas\`. The NAS's address and certificate fingerprint are in that
runner's own configuration, never here.

Keep this repository private: its run logs may show host names and paths.

The environment holds ${SECRETS.map((s) => `\`${s}\``).join(', ')}${Object.keys(LATER_SECRETS).map((s) => `, and \`${s}\``).join('')}.
The Engineer adds them by hand; the harness only checks their names.
`;
}

// Every generated file, as { path: content }.
export function infraFiles({ ref, environment }) {
  const files = { 'README.md': readme({ ref, environment }) };
  for (const c of CALLERS) files[`.github/workflows/${c.file}`] = callerWorkflow(c, { ref, environment });
  return files;
}
